#include <iostream>
#include <vector>
#include <sstream>

int main() {
    int n;
    std::cin >> n;

    std::string edges_str;
    std::cin >> edges_str;

    std::string energy_str;
    std::cin >> energy_str;

    long long K, X;
    std::cin >> K >> X;

    // Parse edges
    std::vector<std::vector<int>> edges;
    if (edges_str.length() > 2) {
        edges_str = edges_str.substr(1, edges_str.length() - 2);
        std::stringstream ss(edges_str);
        std::string token;
        while(std::getline(ss, token, ']')) {
            if (token[0] == ',') token = token.substr(1);
            if (token[0] == '[') token = token.substr(1);
            if (!token.empty()) {
                std::stringstream edge_ss(token);
                int u, v;
                char comma;
                edge_ss >> u >> comma >> v;
                edges.push_back({u, v});
            }
        }
    }

    // Parse energy
    std::vector<long long> energy;
    if (energy_str.length() > 2) {
        energy_str = energy_str.substr(1, energy_str.length() - 2);
        std::stringstream ss(energy_str);
        std::string token;
        while(std::getline(ss, token, ',')) {
            energy.push_back(std::stoll(token));
        }
    }

    Solution sol;
    int result = sol.maxOperationalStations(n, edges, energy, K, X);
    std::cout << result << std::endl;

    return 0;
}

