    campaign_id INT PRIMARY KEY,
    campaign_name VARCHAR(100),
    city VARCHAR(50),
    start_date DATE,
    end_date DATE
);

CREATE TABLE Orders (
    order_id INT PRIMARY KEY,
    customer_id INT,
    campaign_id INT,
    order_date DATE,
    amount DECIMAL(10,2)
);

